# A constructor-only probe cannot detect incorrect lock semantics. This is an
# additional acceptance case for probe 56, not a new inventory item.
LOCK_BEHAVIOR_PROBE = '''import threading

def main() -> int:
    lock = threading.Lock()
    alias = lock
    print(lock.locked())
    print(alias.acquire(False))
    print(lock.locked())
    print(lock.acquire(False))
    alias.release()
    print(lock.locked())
    print(lock.acquire())
    lock.release()
    return 2
'''
